//! One line of a poll cycle, and what a reading adds to its port.

use std::collections::BTreeMap;
use std::str::FromStr;

pub struct Reading {
    pub port: String,
    pub boot: u32,
    pub uptime: u32,
    pub octets: u64,
}

/// A number of decimal digits only: `parse` alone also takes a leading `+`.
fn number<T: FromStr>(text: &str) -> Option<T> {
    if text.bytes().all(|byte| byte.is_ascii_digit()) {
        text.parse().ok()
    } else {
        None
    }
}

/// Reads `PORT BOOT UPTIME OCTETS`; None without exactly these four fields or
/// with a number that does not fit. Only the caller knows the port, so the
/// check of `octets` against the width of the port is its own.
pub fn parse(line: &str) -> Option<Reading> {
    let fields: Vec<&str> = line.split(' ').collect();
    let [port, boot, uptime, octets] = fields[..] else {
        return None;
    };
    Some(Reading {
        port: port.to_string(),
        boot: number(boot)?,
        uptime: number(uptime)?,
        octets: number(octets)?,
    })
}

#[derive(Clone, Copy)]
struct Seen {
    boot: u32,
    octets: u64,
    width: u32,
    owner: u16,
}

impl Seen {
    /// What this reading adds as the one right after `before` in time: the
    /// whole counter after a restart, otherwise the distance the counter moved,
    /// which covers at most one wrap.
    fn adds_after(self, before: Seen) -> u128 {
        let octets = u128::from(self.octets);
        if self.boot > before.boot {
            return octets;
        }
        let modulus = 1u128 << self.width;
        (octets + modulus - u128::from(before.octets)) % modulus
    }
}

#[derive(Default)]
pub struct Tracker {
    /// Every reading of each port by boot and uptime. A late reading can land
    /// anywhere between them, however old it is, so none can be dropped.
    seen: BTreeMap<String, BTreeMap<(u32, u32), Seen>>,
}

impl Tracker {
    /// The customer and the octets `reading` adds to its port: how much it
    /// changes the sum over the readings of the port in time order. That makes
    /// the total independent of the order of arrival, and a reading sent again
    /// adds nothing. A late reading can still add: it can end a boot the next
    /// reading says nothing about, come before the baseline, or show a wrap the
    /// two readings around it hide, since a wrap is only bounded between
    /// neighbours in time. Before the baseline, what shows is what the next
    /// reading counted, so it is that reading's owner's.
    pub fn advance(&mut self, reading: &Reading, width: u32, owner: u16) -> Option<(u16, u128)> {
        let seen = self.seen.entry(reading.port.clone()).or_default();
        let at = (reading.boot, reading.uptime);
        if seen.contains_key(&at) {
            return None;
        }
        let before = seen.range(..at).next_back().map(|(_, found)| *found);
        let after = seen.range(at..).next().map(|(_, found)| *found);
        let this = Seen {
            boot: reading.boot,
            octets: reading.octets,
            width,
            owner,
        };
        seen.insert(at, this);
        match (before, after) {
            (None, None) => None,
            (Some(before), None) => Some((owner, this.adds_after(before))),
            (None, Some(after)) => Some((after.owner, after.adds_after(this))),
            (Some(before), Some(after)) => {
                let added = this.adds_after(before) + after.adds_after(this)
                    - after.adds_after(before);
                Some((owner, added))
            }
        }
    }
}

//! The octets of each customer in the current period, and its frame.

use std::collections::BTreeMap;

#[derive(Default)]
pub struct Usage {
    octets: BTreeMap<u16, u128>,
}

impl Usage {
    /// Adds `octets` to the customer and returns its new usage.
    pub fn add(&mut self, customer: u16, octets: u128) -> u128 {
        let used = self.octets.entry(customer).or_insert(0);
        *used += octets;
        *used
    }

    pub fn of(&self, customer: u16) -> u128 {
        self.octets.get(&customer).copied().unwrap_or(0)
    }

    /// The frame of the period; a new period starts.
    pub fn close(&mut self) -> Vec<u8> {
        let records: Vec<_> = self.octets.iter().filter(|(_, used)| **used > 0).collect();
        let mut out = b"PM1\0".to_vec();
        out.extend_from_slice(&(records.len() as u16).to_le_bytes());
        for (customer, used) in records {
            // A period holds at most 4 TiB minus 1 KiB, so this fits 32 bits.
            let kib = used.div_ceil(1024) as u32;
            out.extend_from_slice(&customer.to_le_bytes());
            out.extend_from_slice(&kib.to_le_bytes());
        }
        self.octets.clear();
        out
    }
}

//! The meter: its configuration, poll cycles and the current period.

use std::collections::{BTreeMap, BTreeSet};

use super::billing::Usage;
use super::counter::{parse, Tracker};

/// The quota that stands for a flat rate in a configuration file.
const FLAT_RATE: u128 = 4294967295;

struct Port {
    width: u32,
    owner: u16,
}

#[derive(Debug, PartialEq)]
pub struct Alert {
    pub customer: u16,
    pub used: u128,
}

#[derive(Debug, Default, PartialEq)]
pub struct Receipt {
    pub rejected: Vec<usize>,
    pub alerts: Vec<Alert>,
}

#[derive(Default)]
pub struct Meter {
    /// The customers with a quota. One on a flat rate has no entry, and neither
    /// has an owner the configuration does not list as a customer.
    quotas: BTreeMap<u16, u128>,
    ports: BTreeMap<String, BTreeMap<u32, Port>>,
    tracker: Tracker,
    usage: Usage,
    alerted: BTreeSet<u16>,
}

impl Meter {
    /// A meter for the text of a configuration file.
    pub fn new(config: &str) -> Meter {
        let mut meter = Meter::default();
        for line in config.lines() {
            let line = line.split('#').next().unwrap_or("");
            let fields: Vec<&str> = line.split_whitespace().collect();
            match fields[..] {
                ["customer", id, quota] => {
                    let id: u16 = id.parse().expect("a customer");
                    let quota: u128 = quota.parse().expect("a quota");
                    if quota != FLAT_RATE {
                        meter.quotas.insert(id, quota);
                    }
                }
                ["port", name, width, owner] => meter.entry(name, width, owner, "0"),
                ["port", name, width, owner, from] => meter.entry(name, width, owner, from),
                _ => {}
            }
        }
        meter
    }

    fn entry(&mut self, name: &str, width: &str, owner: &str, from: &str) {
        let port = Port {
            width: width.parse().expect("a width"),
            owner: owner.parse().expect("an owner"),
        };
        let entries = self.ports.entry(name.to_string()).or_default();
        entries.insert(from.parse().expect("a boot"), port);
    }

    /// Takes one poll cycle.
    pub fn apply(&mut self, cycle: &str) -> Receipt {
        let mut receipt = Receipt::default();
        for (index, line) in cycle.lines().enumerate() {
            let known = parse(line).and_then(|reading| {
                let entries = self.ports.get(&reading.port)?;
                let (_, port) = entries.range(..=reading.boot).next_back()?;
                let fits = u128::from(reading.octets) >> port.width == 0;
                fits.then_some((reading, port.width, port.owner))
            });
            let Some((reading, width, owner)) = known else {
                receipt.rejected.push(index + 1);
                continue;
            };
            let Some((customer, added)) = self.tracker.advance(&reading, width, owner) else {
                continue;
            };
            let used = self.usage.add(customer, added);
            let over = self.quotas.get(&customer).is_some_and(|quota| used > *quota);
            if over && self.alerted.insert(customer) {
                receipt.alerts.push(Alert { customer, used });
            }
        }
        receipt
    }

    /// The octets of the customer in the current period.
    pub fn usage(&self, customer: u16) -> u128 {
        self.usage.of(customer)
    }

    /// Ends the period: its frame, and a new period starts.
    pub fn close_period(&mut self) -> Vec<u8> {
        self.alerted.clear();
        self.usage.close()
    }
}
